--region global define

--endregion

--region import
---@type Engine.Lib.KTool
local KTool                    = CS.Engine.Lib.KTool
---@type MaidCoffeeUtils
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
--endregion

--region define
local TagType = {
    Fight  = 1, --- 战斗 
    Manage = 2, --- 经营
}
--endregion

--- from: Assets/BundleResources/Prefabs/OverseaManage/OverseaManageCatballSkillDescNode.prefab
---@class OverseaManageCatBallSkillDescNode
---@field Env                           	OverseaManageCatBallSkillDescNode       
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TextNumberEnergyPoint         	TMPro.TextMeshProUGUI                   
---@field ImgGoodsIcon                  	Engine.UI.ImageAlterable                
---@field EnergyPoint                   	UnityEngine.RectTransform               
---@field SelectBtnTagManage            	UnityEngine.RectTransform               
---@field NotSelectBtnTagManage         	UnityEngine.RectTransform               
---@field BtnTagManage                  	UnityEngine.RectTransform               
---@field SelectBtnTagFight             	UnityEngine.RectTransform               
---@field NotSelectBtnTagFight          	UnityEngine.RectTransform               
---@field BtnTagFight                   	UnityEngine.RectTransform               
---@field SkillTag                      	UnityEngine.RectTransform               
---@field TextDesc                      	UnityEngine.UI.Text                     
local OverseaManageCatBallSkillDescNode = Class('OverseaManageCatBallSkillDescNode')

function OverseaManageCatBallSkillDescNode:__init()
    self._selectTag = nil
    self.catDojo = nil
    self.vo = nil
end

function OverseaManageCatBallSkillDescNode:__delete()
    self.catDojo = nil
    self.vo = nil
end

function OverseaManageCatBallSkillDescNode:Awake()
    self._selectTag = TagType.Fight
    self._btnTagNodes   = {self.BtnTagFight,    self.BtnTagManage}
    self._selectNodes   = {self.SelectBtnTagFight,    self.SelectBtnTagManage}
    self._unSelectNodes = {self.NotSelectBtnTagFight, self.NotSelectBtnTagManage}
    
end

function OverseaManageCatBallSkillDescNode:Start()
    SetButtonAction(self.BtnTagFight,  Bind(self, self.OnClickBtnTagFightAction))
    SetButtonAction(self.BtnTagManage, Bind(self, self.OnClickBtnTagManageAction))
end

function OverseaManageCatBallSkillDescNode:OnDestroy()

    self.controller = nil--luabehaviour 中CSharp
    self:Delete()
    self = nil
end

--region init

function OverseaManageCatBallSkillDescNode:InitAllDescFreshBtnShowState(star, vo)
    local t = {}
    local newSelectTag = nil
    for i, selectTag in pairs(TagType) do
        local desc = self:GetSkillDesc(selectTag, star, vo)
        t[selectTag] = desc
        local isShowBtn = not string.isEmpty(desc)
        KTool.SetActive(self._btnTagNodes[selectTag].gameObject, isShowBtn)
        if isShowBtn and newSelectTag == nil then
            newSelectTag = selectTag
        end
    end
    return t, newSelectTag
end

--endregion


--region logic

---FreshUI
---@param catData CatEggDojo
---@param vo MaidCoffeeCatRollConfigVo
function OverseaManageCatBallSkillDescNode:FreshUI(catData, vo, customTag)
    self.catDojo = catData
    self.vo = vo
    local isLock     = catData == nil
    local star       = isLock and 0 or checkNumber(catData.star) 
    local level      = isLock and 1 or checkNumber(catData.level) 
    local cafeEnergy = isLock and vo.energy or checkNumber(catData.cafeEnergy) 
    
    local tag2Desc, newSelectTag = self:InitAllDescFreshBtnShowState(star, vo)
    if customTag then
        self._selectTag = customTag
    elseif newSelectTag ~= self._selectTag then
        self._selectTag = newSelectTag
    end
    self._tag2Desc = tag2Desc
    
    self:FreshTagSelectState()
    self:FreshDesc(star, vo)
    self:FreshEnergyPoint(level, cafeEnergy, vo)
     
end

function OverseaManageCatBallSkillDescNode:FreshTagSelectState()
    KTool.SetActive(self.SkillTag.gameObject, true)
    
    local selectTag = self._selectTag
    for i, v in ipairs(self._selectNodes) do
        KTool.SetActive(v.gameObject, i == selectTag)
    end
    for i, v in ipairs(self._unSelectNodes) do
        KTool.SetActive(v.gameObject, i ~= selectTag)
    end
    
end

---FreshDesc
---@param vo MaidCoffeeCatRollConfigVo
function OverseaManageCatBallSkillDescNode:FreshDesc(star, vo)
    local desc = self._tag2Desc[self._selectTag]
    self.TextDesc.text = desc
    
end

function OverseaManageCatBallSkillDescNode:FreshEnergyPoint(level, cafeEnergy, vo)
    local isFight = self._selectTag == TagType.Fight
    KTool.SetActive(self.EnergyPoint.gameObject, isFight)
    if isFight then
        self.TextNumberEnergyPoint.text = string.format("%s/%s", cafeEnergy, MaidCoffeeUtils.CalcCatRollEnergyLimit(vo.id, level))
    end
end

function OverseaManageCatBallSkillDescNode:FreshGoodsDesc(desc)
    KTool.SetActive(self.SkillTag.gameObject, false)
    KTool.SetActive(self.EnergyPoint.gameObject, false)
    self.TextDesc.text = desc
    
end

--endregion


--region get/set

---GetSkillDesc
---@param vo MaidCoffeeCatRollConfigVo
function OverseaManageCatBallSkillDescNode:GetSkillDesc(selectTag, star, vo)
    local isSelectFightTag = selectTag == TagType.Fight
    local desc
    if isSelectFightTag then
        ---@type MaidCoffeeCatRollSkillGrowVo
        local growVo = MaidCoffeeUtils.GetMaidCoffeeCatRollSkillGrowVo(vo.skillId, star)
        if growVo then
            ---@type QuestUpBuffVo
            local questBuffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(growVo.skillNumId)
            desc = questBuffVo.desc
        end
        
    else
        ---存在经营技能
        ---@type MaidCoffeeSkillVo
        local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(vo.coffee)
        if skillVo then
            desc = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr, vo.coffeeNum,nil,vo.percentage)
            
        end
        
    end
    return desc
end

--endregion


--region handler

function OverseaManageCatBallSkillDescNode:OnClickBtnTagFightAction()
    if self._selectTag == TagType.Fight then return end
    --self._selectTag = TagType.Fight
    self:FreshUI(self.catDojo, self.vo, TagType.Fight)
    
end

function OverseaManageCatBallSkillDescNode:OnClickBtnTagManageAction()
    if self._selectTag == TagType.Manage then return end
    self:FreshUI(self.catDojo, self.vo, TagType.Manage)
    
end

--endregion

return OverseaManageCatBallSkillDescNode